import heapq

def program(xs):
    """Return the three largest numbers of xs (or all of them if fewer than three), sorted ascending.
    """
    if len(xs) <= 3:
        return sorted(xs)
    # Get three largest values (duplicates kept) in descending order
    top_three = heapq.nlargest(3, xs)
    return sorted(top_three)

