def program(xs):
    """Return the three largest numbers of xs sorted ascending.
    If xs has fewer than three elements, return all of them sorted.
    """
    if len(xs) <= 3:
        return sorted(xs)
    # Get three largest elements (descending order), then sort ascending
    top_three_desc = sorted(xs, reverse=True)[:3]
    return sorted(top_three_desc)

