import sys
from collections import Counter

def program(xs):
    """Return a list containing (max frequency of any element in xs) minus one.
    If xs is empty, returns [0]."""
    if not xs:
        return [0]
    freq = Counter(xs)
    max_count = max(freq.values())
    return [max_count - 1 if max_count > 0 else 0]

